    if ((ticks - 1UL) > SysTick_LOAD_RELOAD_Msk) {
    return (1UL);
    }

    // 设置重装载寄存器
    SysTick->LOAD = (uint32_t)(ticks - 1UL);

    // 设置中断优先级
    NVIC_SetPriority (SysTick_IRQn, (1UL << __NVIC_PRIO_BITS) - 1UL);

    // 设置当前数值寄存器
    SysTick->VAL = 0UL;

    // 设置系统定时器的时钟源为 AHBCLK=168M
